package wtmodern;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraftforge.common.util.FakePlayerFactory;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.resources.ResourceLocation;
import tc4revival.research.*;
import java.util.UUID;

@GameTestHolder("warptheory") @PrefixGameTestTemplate(false)
public class WarpServerTests {
    @GameTest(template="empty")
    public static void litmusPaperPreservesOriginalConsumptionThreshold(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("7fbdf45c-1e22-4b8a-8921-2a574f907916"),"WarpPaperTester"));p.getAbilities().instabuild=false;var store=KnowledgeSavedData.get(p.server);for(int amount:new int[]{10,11}){store.update(p.getUUID(),n->0,k->{k.setWarp(PlayerKnowledge.WarpKind.PERMANENT,0);k.setWarp(PlayerKnowledge.WarpKind.STICKY,0);k.setWarp(PlayerKnowledge.WarpKind.TEMPORARY,amount);return null;});var paper=new ItemStack(Content.PAPER.get(),2);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,paper);Content.PAPER.get().use(h.getLevel(),p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(paper.getCount()==(amount<=10?1:2),"Original paper consumes only at ten or less total warp");}p.getInventory().clearContent();pass(h);}
    @GameTest(template="empty",timeoutTicks=80)
    public static void fakeSoundsQueueAtOriginalSeverityAndCadence(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("a2f4a32f-63bc-4524-9c84-e9d4a112846c"),"WarpSoundTester"));p.setPos(h.absoluteVec(new net.minecraft.world.phys.Vec3(2,3,2)));positiveWarp(p);WarpState.tag(p).getAllKeys().clear();h.assertTrue(WarpRules.find("fakeexplosion").severity()==10&&WarpRules.find("fakecreeper").severity()==10,"Distance parameters are not event severity");for(String id:new String[]{"fakeexplosion","fakecreeper"}){WarpEvents.start(p,id);WarpEvents.start(p,id);h.assertTrue(WarpState.tag(p).getInt(id)==2,"Events accumulate instead of playing immediately");}p.setYHeadRot(0);var behind=WarpEvents.fakeSoundPosition(p,"fakecreeper");h.assertTrue(behind.distanceTo(p.position().add(0,0,-2))<.001,"Original zero-yaw creeper position retained");for(int i=0;i<64;i++){var pos=WarpEvents.fakeSoundPosition(p,"fakeexplosion");h.assertTrue(pos.x>=(int)p.getX()-8&&pos.x<(int)p.getX()+8&&pos.y>=(int)p.getY()-8&&pos.y<(int)p.getY()+8&&pos.z>=(int)p.getZ()-8&&pos.z<(int)p.getZ()+8,"Explosion plays inside original uniform sixteen-block cube");}for(int tick=1;tick<=40;tick++)h.runAfterDelay(tick,()->WarpEvents.runActive(p));h.runAfterDelay(42,()->{h.assertTrue(!WarpState.tag(p).contains("fakeexplosion")&&!WarpState.tag(p).contains("fakecreeper"),"Exactly two world-second boundaries consume two queued sounds");pass(h);});}
    private static void positiveWarp(net.minecraft.server.level.ServerPlayer p){p.getAbilities().instabuild=false;p.removeAllEffects();KnowledgeSavedData.get(p.server).update(p.getUUID(),n->0,k->{k.setWarp(PlayerKnowledge.WarpKind.TEMPORARY,100);return null;});}
    private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WARPTHEORY_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
    @GameTest(template="empty")
    public static void potionEventsAndNonEdibleTalisman(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("dfbe7b5e-25dd-4b64-b01f-23d9f52c6a14"),"WarpPotionTester"));positiveWarp(p);for(var id:new String[]{"poison","nausea","jump","blind"})h.assertTrue(WarpEvents.start(p,id),"Potion event starts: "+id);h.assertTrue(p.getEffect(net.minecraft.world.effect.MobEffects.JUMP).getAmplifier()==20,"Original exceptional jump amplifier");var poison=p.getEffect(net.minecraft.world.effect.MobEffects.POISON);h.assertTrue(poison.getDuration()==400&&poison.getCurativeItems().isEmpty(),"Warp potion is not milk-curable");WarpEvents.start(p,"poison");h.assertTrue(p.getEffect(net.minecraft.world.effect.MobEffects.POISON).getDuration()==800,"Repeated effect adds duration");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Content.AMULET.get()));h.assertTrue(Content.AMULET.get().use(h.getLevel(),p,net.minecraft.world.InteractionHand.MAIN_HAND).getResult()==net.minecraft.world.InteractionResult.PASS,"Talisman cannot be eaten");pass(h);}
    @GameTest(template="empty")
    public static void swampContainmentAndNames(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(3,2,3));l.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());for(var direction:net.minecraft.core.Direction.values())if(direction!=net.minecraft.core.Direction.UP)l.setBlockAndUpdate(pos.relative(direction),Blocks.STONE.defaultBlockState());h.assertTrue(WarpEvents.canTurnToSwampWater(l,pos),"Contained air can become swamp water");l.setBlockAndUpdate(pos.north(),Blocks.WATER.defaultBlockState());h.assertTrue(WarpEvents.canTurnToSwampWater(l,pos),"Existing water contains swamp pools");l.setBlockAndUpdate(pos.north(),Blocks.AIR.defaultBlockState());h.assertTrue(!WarpEvents.canTurnToSwampWater(l,pos),"Open sides cannot flood");var groups=FriendNames.parse(java.util.List.of("-ka +c","-br +v","ve","al","+ro","+is"));for(int i=0;i<50;i++){String name=FriendNames.compose(groups,2,l.random);h.assertTrue(name.equals("Karo")||name.equals("Bris"),"Name follows next-syllable constraints: "+name);}pass(h);}
    @GameTest(template="empty")
    public static void warpRemovalAndPurgeQueue(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("e5a2c2e3-8989-426a-8a1e-d6f8b53f60e1"),"WarpTester"));var d=KnowledgeSavedData.get(p.server);d.update(p.getUUID(),p.getRandom()::nextInt,k->{k.setWarp(PlayerKnowledge.WarpKind.PERMANENT,10);k.setWarp(PlayerKnowledge.WarpKind.STICKY,3);k.setWarp(PlayerKnowledge.WarpKind.TEMPORARY,2);return null;});WarpState.remove(p,8);var k=WarpState.knowledge(p);h.assertTrue(k.warp(PlayerKnowledge.WarpKind.PERMANENT)==9&&k.warp(PlayerKnowledge.WarpKind.STICKY)==0&&k.warp(PlayerKnowledge.WarpKind.TEMPORARY)==0,"Removal pays temporary and normal first, then original integer permanent cost");WarpState.purge(p);h.assertTrue(WarpState.knowledge(p).totalWarp()==0,"Tear removes all warp");WarpEvents.tickPlayer(p);h.assertTrue(WarpState.tag(p).getList("queue",8).isEmpty(),"Zero warp discards legacy rebound before execution");pass(h);}
    @GameTest(template="empty",timeoutTicks=160)
    public static void vanishedChestRestoresInventoryWithoutDrops(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,2,1));var l=h.getLevel();l.setBlockAndUpdate(pos,Blocks.CHEST.defaultBlockState());var chest=(ChestBlockEntity)l.getBlockEntity(pos);chest.setItem(0,new ItemStack(Items.DIAMOND,17));h.assertTrue(VanishingBlock.hide(l,pos,l.getGameTime()+10),"Chest was hidden");h.assertTrue(l.getBlockEntity(pos) instanceof VanishingBlock.Snapshot,"Restorable block entity exists");var saved=l.getBlockEntity(pos).saveWithFullMetadata();((VanishingBlock.Snapshot)l.getBlockEntity(pos)).load(saved);h.runAfterDelay(15,()->{h.assertTrue(l.getBlockEntity(pos) instanceof ChestBlockEntity,"Restored chest entity");h.assertTrue(((ChestBlockEntity)l.getBlockEntity(pos)).getItem(0).getCount()==17,"All items restored");h.assertTrue(l.getEntitiesOfClass(ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(2)).isEmpty(),"Replacement creates no duplicate drops");pass(h);});}
    @GameTest(template="empty")
    public static void researchAndRecipesAvailable(GameTestHelper h){boolean easy=WarpConfig.EASY.get();for(var id:new String[]{"pure_tear","pure_talisman","litmus_paper","something_chicken","something_beef","something_porkchop","something_cod"}){h.assertTrue(h.getLevel().getRecipeManager().byKey(new ResourceLocation("warptheory",id+(easy?"_easy":""))).isPresent(),"Missing active acquisition recipe "+id);h.assertTrue(h.getLevel().getRecipeManager().byKey(new ResourceLocation("warptheory",id+(easy?"":"_easy"))).isEmpty(),"Inactive recipe branch must not remain craftable: "+id);}for(var key:new String[]{"WARPCLEANSER","WARPAMULET","WARPPAPER","WARPSOMETHING"})h.assertTrue(ResearchCatalogs.catalog().find("warptheory:"+key).isPresent(),"Missing research "+key);pass(h);}
    @GameTest(template="empty")
    public static void passiveFriendCannotIgnite(GameTestHelper h){var creeper=Content.FRIEND.get().create(h.getLevel());creeper.ignite();h.assertTrue(!creeper.isIgnited()&&creeper.getSwellDir()==-1,"Friend remains harmless even after attempted ignition");h.assertTrue(creeper.getMaxHealth()==100,"Legacy friend health is 100");pass(h);}
    @GameTest(template="empty")
    public static void decayPreservesLegacyChain(GameTestHelper h){h.assertTrue(WarpEvents.decayState(Blocks.STONE.defaultBlockState()).is(Blocks.COBBLESTONE),"stone to cobble");h.assertTrue(WarpEvents.decayState(Blocks.COBBLESTONE.defaultBlockState()).is(Blocks.GRAVEL),"cobble to gravel");h.assertTrue(WarpEvents.decayState(Blocks.GRAVEL.defaultBlockState()).is(Blocks.SAND),"gravel to sand");h.assertTrue(WarpEvents.decayState(Blocks.SAND.defaultBlockState()).isAir(),"sand to air");h.assertTrue(WarpEvents.decayState(Blocks.BEDROCK.defaultBlockState())==null,"unmapped blocks unchanged");pass(h);}
}
